cat > src/orchestration/chatOrchestrator.acceptance.test.ts <<'EOF'
import {createChatOrchestrator} from './chatOrchestrator.js';
import type {OrchestratorHooks} from './chatOrchestrator.js';
import type {AIProvider, MessageChunk} from '../types/ai.js';
import type {ChatSession} from '../types/session.js';
import {PromptBuilder} from '../infrastructure/builders/promptBuilder.js';

const SENT_AT = '2026-01-01T00:00:00.000Z';

const session = (): ChatSession => ({
  sessionId: 's1',
  userId: 'u1',
  entries: [{role: 'user', content: 'hello', timestamp: SENT_AT}],
});

// A provider whose stream rejects with an arbitrary value, the way a library with its own error shape would.
const rejectingProvider = (rejection: unknown): AIProvider => ({
  // eslint-disable-next-line require-yield
  async *sendMessage(): AsyncGenerator<MessageChunk> {
    throw rejection;
  },
  async generateStructured<T>(): Promise<T> {
    return {} as T;
  },
});

const promptBuilder = new PromptBuilder({identity: 'You are a test assistant.'});

const settle = (call: Promise<unknown>): Promise<{rejected: boolean; value: unknown}> =>
  call.then(
    value => ({rejected: false, value}),
    (value: unknown) => ({rejected: true, value})
  );

describe('specs/hal-engine-config-hooks/spec.md#7 onError for a rejection that is not an Error', () => {
  it.each([
    ['a string', 'provider exploded'],
    ['a plain object', {code: 'E_UPSTREAM', status: 503}],
    ['undefined', undefined],
  ])(
    'calls onError once with an Error whose cause is %s, and the caller still receives the original rejection',
    async (_label, rejection) => {
      const seen: {isError: boolean; cause: unknown}[] = [];
      const hooks: OrchestratorHooks = {
        onError: async (_session, error) => {
          seen.push({isError: error instanceof Error, cause: (error as {cause?: unknown}).cause});
        },
      };

      const orchestrator = createChatOrchestrator(rejectingProvider(rejection), promptBuilder, undefined, {hooks});
      const outcome = await settle(orchestrator.processMessage(session()));

      expect({outcome, seen}).toEqual({
        outcome: {rejected: true, value: rejection},
        seen: [{isError: true, cause: rejection}],
      });
      // toEqual is structural; the caller must get the very value the provider threw, not a copy or a wrapper.
      expect(outcome.value).toBe(rejection);
    }
  );
});
EOF
npx prettier --write src/orchestration/chatOrchestrator.acceptance.test.ts >/dev/null
NODE_OPTIONS=--experimental-vm-modules npx jest --runTestsByPath src/orchestration/chatOrchestrator.acceptance.test.ts 2>&1 | grep -v "^\s*at " | head -80
